pipeline {
    agent any

    environment {
        GROUP_NAME = null
        PROJECT_NAME = null
        VERSION = null
        PORT = 11015
        REMOTE_HOST = '10.0.0.22' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'jenkins-server-ssh-private-key' // Jenkins中保存的远程服务器SSH凭证ID
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC'))
        REMOTE_DIR = '/data/dsj/lead_analytics'  // 远程服务器上的目标目录
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit (branches: [[name:
                "${params.Branch}"]],extensions: [],userRemoteConfigs: [[credentialsId:
                'SSH-KEY-FOR-GITLAB', url:'ssh://git@106.227.89.18:10093/yzt/lead-analytics.git']])
            }
        }

        stage('Mvn Compile') {
            steps {
                script {
                    def pom = readMavenPom file:
                    'pom.xml'
                    GROUP_NAME = pom.groupId
                    PROJECT_NAME = pom.artifactId
                    VERSION = pom.version
                    echo "PROJECT_NAME：${PROJECT_NAME}"
                    sh "mvn clean"
                    sh "mvn install -Dmaven.test.skip=true"
                }
            }
        }


        stage('Rename Backup') {
            steps {
                script {
                    // 切换至远程服务器，备份原有jar包
                    def jarName = "${PROJECT_NAME}-${VERSION}" // 根据项目名称和版本构造 jar 包名

                    sh """
                        ssh ${REMOTE_USER}@${REMOTE_HOST} '
                            if [ ! -d "${REMOTE_DIR}" ]; then
                                mkdir -p ${REMOTE_DIR}
                            fi

                            cd ${REMOTE_DIR}

                            if [ -e "analytics-server-${VERSION}.jar" ]; then
                                mv  "analytics-server-${VERSION}.jar"  "analytics-server-${VERSION}.jar-${TIMESTAMP}" 
                            fi

                        '
                    """
                }
            }
        }


        stage('Deploy to Remote Server') {
            steps {
                script {
                    def jarName = "${PROJECT_NAME}-${VERSION}.jar" // 根据项目名称和版本构造 jar 
                    def jobName = env.JOB_NAME
                    def currentWorkspace = pwd()
                    echo "jarName：${jarName}"
                    echo "当前工作空间：${currentWorkspace}"

                    // 将 jar 包复制到远程服务器
                    sh "scp ${currentWorkspace}/analytics-server/target/analytics-server-${VERSION}.jar ${REMOTE_USER}@${REMOTE_HOST}:${REMOTE_DIR}"

                    // 在远程服务器上执行命令
                    sh """
                        ssh ${REMOTE_USER}@${REMOTE_HOST} '

                        cd ${REMOTE_DIR}  &&

                        sh /data/dsj/api_run.sh restart ${PORT} test ${REMOTE_DIR}/analytics-server-${VERSION}.jar

                        '
                    """

                }
            }
        }

    }

}
